pair A,B,C,D,E,F,G,H;

A=(0,0);
B=(1,0);
C=(1,1);
D=(0,1);
E=(0.3,1.5);
F=C+(E-D);
G=B+(E-D);
H=A+(E-D);

draw(A--B--C--D--A--H--E);
draw(D--C--F);
draw(H--G);
draw(D--E--F--G--B);

dot(A);
dot(B);
dot(C);
dot(D);
dot(E);
dot(F);
dot(G);
dot(H);

