F=(0,0);
D=(6,0);
I=(10,0);
A=(15,0);
B=(15,8);
H=(9,8);
C=(6,8);
G=(0,20);
draw(A--B--C--D--cycle,linewidth(0.7));
draw(A--F--G--cycle,linewidth(0.7));
draw(G--I,linewidth(0.7));
label("4",(8,0),S);
label("8",(15,4),E);
label("6",(12,8),N);
label("$A$",A,SE);
label("$B$",B,NE);
label("$C$",C,W);
label("$D$",D,S);
label("$E$",I,S);
label("$F$",F,W);
label("$G$",G,W);
label("$H$",H,NE);
